+        
+        // Brief delay before loading next question
+        setTimeout(() => {
+            activeWordDuelIndex++;
+            window.renderWordDuelQuestion();
+        }, 800);
+    } else {
+        // Wrong answer
+        feedback.className = 'word-feedback wrong-answer';
+        feedback.innerText = '✗ SALAH! Coba lagi.';
+    }
+};
