window.markTrainingCompleted = function(id) {
    // Gunakan custom toast-based confirmation agar tidak diblokir browser
    const trainings = JSON.parse(localStorage.getItem("pa_trainings")) || [];
    const t = trainings.find(x => x.id === id);
    if (!t) {
        if (window.showToast) window.showToast("Training tidak ditemukan.", "error");
        return;
    }

    if (t.status === "Completed") {
        if (window.showToast) window.showToast("Training ini sudah ditandai selesai.", "info");
        return;
    }

    // Konfirmasi menggunakan window.confirm (fallback aman) atau lanjut langsung
    const doComplete = () => {
        const trainingsNow = JSON.parse(localStorage.getItem("pa_trainings")) || [];
        const target = trainingsNow.find(x => x.id === id);
        if (target) {
            target.status = "Completed";
            localStorage.setItem("pa_trainings", JSON.stringify(trainingsNow));
            // Refresh tampilan Trainer
            if (typeof window.renderTrainerTrainings === 'function') window.renderTrainerTrainings();
            // Refresh tampilan Agen juga agar langsung ter-update
            if (typeof window.renderAgenTrainings === 'function') window.renderAgenTrainings();
            if (window.showToast) window.showToast("✅ Training berhasil dinyatakan SELESAI! Agen yang RSVP kini dapat konfirmasi kehadiran dengan token.", "success");
        }
    };

    // Coba window.confirm; jika diblokir/null, langsung eksekusi
    try {
        const confirmed = window.confirm("Nyatakan kelas ini telah selesai? Agen yang sudah RSVP akan dapat mengonfirmasi kehadiran dengan token.");
        if (confirmed) doComplete();
    } catch (e) {
        // Jika confirm() diblokir, langsung jalankan
        doComplete();
    }
};

